<?php
namespace App\Notifications;
use App\Models\EmployeeContract; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class ContractExpiringNotification extends Notification implements ShouldQueue { use Queueable; public function __construct(public int $contractId,public string $employeeName,public string $endDate){} public static function fromContract(EmployeeContract $c):self{return new self($c->id,$c->employee->name,$c->end_date->toDateString());} public function via(object $notifiable):array{return filled($notifiable->email)?['database','mail']:['database'];} public function toArray(object $notifiable):array{return ['kind'=>'contract_expiring','contract_id'=>$this->contractId,'employee_name'=>$this->employeeName,'end_date'=>$this->endDate,'message'=>"{$this->employeeName} contract expires {$this->endDate}."]; } public function toMail(object $notifiable):MailMessage{return (new MailMessage)->subject('Payra contract expiry')->line("{$this->employeeName}'s contract expires on {$this->endDate}.")->action('Review contracts',url('/contracts'));} }
